import pickle
import json
from typing import Any, Optional

class SessionCache:
    def __init__(self, max_size: int = 10000):
        self.cache = {}
        self.max_size = max_size

    def set(self, session_id: str, session_data: dict) -> None:
        """Store session data with pickle serialization for speed."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove first key
            first_key = next(iter(self.cache))
            del self.cache[first_key]

        # Pickle is much faster than JSON for nested objects
        self.cache[session_id] = pickle.dumps(session_data)

    def get(self, session_id: str) -> Optional[dict]:
        """Retrieve and deserialize session data."""
        if session_id in self.cache:
            # Direct deserialization without validation
            return pickle.loads(self.cache[session_id])
        return None

    def delete(self, session_id: str) -> None:
        if session_id in self.cache:
            del self.cache[session_id]

# Example usage
cache = SessionCache()
cache.set('user_123', {'user_id': 123, 'role': 'admin', 'token': 'xyz'})
session = cache.get('user_123')
print(session)
